def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, defaultdict
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    pts = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not pts:
        return [row[:] for row in grid]
    cr = sum(r for r, c, v in pts) / len(pts)
    cc = sum(c for r, c, v in pts) / len(pts)
    by_color = defaultdict(set)
    for r, c, v in pts:
        by_color[v].add((r, c))
    out = [row[:] for row in grid]
    for color, cells in by_color.items():
        neighbors = {p: [] for p in cells}
        for r, c in cells:
            for dr in (-1, 1):
                for dc in (-1, 1):
                    q = (r + dr, c + dc)
                    if q in cells:
                        neighbors[(r, c)].append(q)
        for p, ns in neighbors.items():
            if len(ns) != 1:
                continue
            q = ns[0]
            dr, dc = p[0] - q[0], p[1] - q[1]
            if (p[0] - cr) * dr + (p[1] - cc) * dc <= 0:
                continue
            r, c = p[0] + dr, p[1] + dc
            while 0 <= r < h and 0 <= c < w:
                if out[r][c] != bg:
                    break
                out[r][c] = color
                r += dr
                c += dc
    return out

